create table if not exists public.tracks (id bigint generated by default as identity primary key, title text not null, artist_source text not null default '', mood_genre text not null default 'Khác', status text not null default 'Chưa dùng' check (status in ('Chưa dùng','Đã dùng')), audio_url text not null default '', notes text not null default '', created_at timestamptz not null default now());
create table if not exists public.ideas (id bigint generated by default as identity primary key, title text not null, status text not null default 'Lên ý tưởng' check (status in ('Lên ý tưởng','Kịch bản','Quay video','Edit','Đã đăng')), concept text not null default 'Khác', priority smallint not null default 2 check (priority between 1 and 3), publish_date date, hook text not null default '', main_content text not null default '', audio_sfx text not null default '', hashtag jsonb not null default '[]'::jsonb, reference_url text not null default '', notes text not null default '', track_id bigint references public.tracks(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.config_presets (id bigint generated by default as identity primary key, group_name text not null, attribute text not null, value text not null default '', notes text not null default '', link_example text not null default '');
create table if not exists public.editing_shortcuts (id bigint generated by default as identity primary key, category text not null, key_combo text not null, action text not null, notes text not null default '');
create table if not exists public.production_sops (id bigint generated by default as identity primary key, type text not null, category_or_profile text not null, recommended_mode text not null default '', do_instructions text not null default '', dont_instructions text not null default '', camera_settings text not null default '', post_process text not null default '');
create index if not exists ideas_status_idx on public.ideas(status); create index if not exists ideas_publish_date_idx on public.ideas(publish_date); create index if not exists ideas_track_id_idx on public.ideas(track_id);